      SUBROUTINE RCALCCC     CALCULATION OF TRANSFER MATRIX WHEN IT IS TO BE PRINTEDCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'R2P.CIN'C-----------------------------------------------------------------------C      IF (CDB .EQ. 14) GO TO 260      IF (CDB .EQ. 24) GO TO 10      IF (RCP) GO TO 100CC     DESIRED MATRIX EQUALS R2 MATRIXC   10 CALL R2TORS      IF (CDB .LT. 0) GO TO 300      GO TO 400CC     DESIRED MATRIX EQUALS RC MATRIXC  100 IF (R2P) GO TO 200      CALL RCTORS      IF (CDB .LT. 0) GO TO 300      GO TO 400CC     DESIRED MATRIX EQUALS RC2 TIMES RCC  200 CALL MR2RC      IF (CDB .LT. 0) GO TO 300      GO TO 400CC     DESIRED MATRIX EQUALS R MATRIX (INDIVIDUAL ELEMENT)C  260 CALL RTORS      GO TO 400CC     FIND INVERSE MATRIXC  300 CALL RINVC  400 RETURN      END